#include "Plugin.mm"
#include <cassert>
bool DLSSListenerReady(){return true;}
static Completion pending;static void*context;
static void fake(const uint8_t*,size_t,int32_t,int32_t,int32_t,const char*,const char*,void*c,Completion cb){context=c;pending=cb;}
static Panel*makePanel(){Panel*p=[Panel new];p.window=[[NSWindow alloc]initWithContentRect:NSMakeRect(0,0,100,100) styleMask:NSWindowStyleMaskTitled backing:NSBackingStoreBuffered defer:NO];p.profile=[NSPopUpButton new];[p.profile addItemsWithTitles:@[@"Off",@"Natural",@"Standard",@"Cinematic",@"Neutral"]];p.quality=[NSPopUpButton new];[p.quality addItemsWithTitles:@[@"320 px",@"384 px",@"512 px",@"640 px",@"768 px",@"960 px",@"1280 px",@"1920 px"]];p.sliders=[NSMutableArray array];for(int i=0;i<8;i++)[p.sliders addObject:[NSSlider sliderWithValue:i==5?4:1 minValue:0 maxValue:12 target:nil action:nil]];p.skin=[NSButton new];p.automatic=[NSButton new];p.automatic.state=NSControlStateValueOn;p.apply=[NSButton new];p.run=[NSButton new];p.cancel=[NSButton new];p.stop=[NSButton new];p.status=[NSTextField new];p.view=[Preview new];p->input={1,2,3,255};p->output={9,9,9,255};p->width=p->height=1;p->process=fake;p->resources=@"/tmp";return p;}
static void finish(){uint8_t b[]={4,5,6,255};pending(context,b,4,nullptr);for(int i=0;i<10;i++)[[NSRunLoop currentRunLoop]runUntilDate:[NSDate dateWithTimeIntervalSinceNow:.01]];}
int main(){@autoreleasepool{[NSApplication sharedApplication];NSString*key=@"com.local.dlss5.native.lastSession";id old=[[NSUserDefaults standardUserDefaults]objectForKey:key];Panel*a=makePanel();a.sliders[0].doubleValue=.35;[a.profile selectItemAtIndex:2];a.automatic.state=NSControlStateValueOff;[a remember];assert([[[NSUserDefaults standardUserDefaults]dictionaryForKey:key]objectForKey:@"settings"]==nil);[[NSUserDefaults standardUserDefaults]setObject:@{@"automatic":@NO,@"settings":a.settings} forKey:key];Panel*b=makePanel();[b restore];assert(b.automatic.state==NSControlStateValueOff&&b.profile.indexOfSelectedItem==0&&fabs(b.sliders[0].doubleValue-1)<.0001);b.automatic.state=NSControlStateValueOn;[b render:nil];assert(!b.busy&&!b.apply.enabled&&b->output==b->input);[b.profile selectItemAtIndex:1];b->output={9,9,9,255};[b render:nil];assert(b.busy&&b.stop.enabled&&!b.processingOverlay.hidden);[b interrupt:nil];assert(b.cancelRequested&&!b.apply.enabled);finish();assert(b.processingOverlay.hidden);assert(!b.busy&&!b.apply.enabled&&!b.stop.enabled&&b->output[0]==9);assert(b.automatic.state==NSControlStateValueOn);[b render:nil];finish();assert(b.apply.enabled&&b->output[0]==4&&!b.cancelRequested);if(old)[[NSUserDefaults standardUserDefaults]setObject:old forKey:key];else [[NSUserDefaults standardUserDefaults]removeObjectForKey:key];puts("PASS: only auto-off restored; legacy settings ignored; interrupted output discarded; auto preference preserved; next preview succeeds");}}
